if typ.Kind() == reflect.Map && typ.Key().Kind() == reflect.String {
	k := typ.Elem().Kind()
	isElemInterface := k == reflect.Interface
	isElemSlice := k == reflect.Slice
	isElemString := k == reflect.String
	isElemBool := k == reflect.Bool
	isElemInt := k >= reflect.Int && k <= reflect.Int64
	isElemUint := k >= reflect.Uint && k <= reflect.Uint64
	isElemFloat := k >= reflect.Float32 && k <= reflect.Float64
	isElemTime := typ.Elem() == reflect.TypeOf(time.Time{})

	if !(isElemSlice || isElemString || isElemBool || isElemInt || isElemUint || isElemFloat || isElemTime || isElemInterface) {
		return errors.New("binding to map with type " + typ.Elem().String() + " is not supported")
	}

	if val.IsNil() {
		val.Set(reflect.MakeMap(typ))
	}

	for key, values := range data {
		if isElemSlice {
			sliceOf := typ.Elem().Elem().Kind()
			slice := reflect.MakeSlice(typ.Elem(), len(values), len(values))
			for i := 0; i < len(values); i++ {
				if err := setWithProperType(sliceOf, values[i], slice.Index(i)); err != nil {
					return err
				}
			}
			val.SetMapIndex(reflect.ValueOf(key), slice)
		} else if isElemInterface {
			val.SetMapIndex(reflect.ValueOf(key), reflect.ValueOf(values))
		} else {
			elem := reflect.New(typ.Elem()).Elem()
			if isElemTime {
				// time.Time implements encoding.TextUnmarshaler on its pointer receiver, but
				// setWithProperType cannot handle it as it is a struct kind without a
				// BindUnmarshaler/TextUnmarshaler aware path for the "unknown type" case.
				if unmarshaler, ok := elem.Addr().Interface().(encoding.TextUnmarshaler); ok {
					if err := unmarshaler.UnmarshalText([]byte(values[0])); err != nil {
						return err
					}
					val.SetMapIndex(reflect.ValueOf(key), elem)
					continue
				}
			}
			if err := setWithProperType(typ.Elem().Kind(), values[0], elem); err != nil {
				return err
			}
			val.SetMapIndex(reflect.ValueOf(key), elem)
		}
	}
	return nil
}

