package echo

import (
	"crypto/tls"
	"net/http"
	"testing"
)

func TestTmpScheme(t *testing.T) {
	tests := []struct {
		name    string
		request *http.Request
		want    string
	}{
		{"TLS", &http.Request{TLS: &tls.ConnectionState{}}, "https"},
		{"XFP https", &http.Request{Header: http.Header{HeaderXForwardedProto: []string{"https"}}}, "https"},
		{"XFP invalid + XFProtocol https", &http.Request{Header: http.Header{HeaderXForwardedProto: []string{"invalid"}, HeaderXForwardedProtocol: []string{"https"}}}, "https"},
		{"XFProtocol http", &http.Request{Header: http.Header{HeaderXForwardedProtocol: []string{"http"}}}, "http"},
		{"XForwardedSsl on", &http.Request{Header: http.Header{HeaderXForwardedSsl: []string{"on"}}}, "https"},
		{"XUrlScheme https", &http.Request{Header: http.Header{HeaderXUrlScheme: []string{"https"}}}, "https"},
		{"all invalid", &http.Request{Header: http.Header{
			HeaderXForwardedProto:    []string{"invalid"},
			HeaderXForwardedProtocol: []string{"invalid"},
			HeaderXForwardedSsl:      []string{"invalid"},
			HeaderXUrlScheme:         []string{"invalid"},
		}}, "http"},
		{"no headers", &http.Request{}, "http"},
		{"XFP HTTPS", &http.Request{Header: http.Header{HeaderXForwardedProto: []string{"HTTPS"}}}, "HTTPS"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			c := &context{request: tt.request}
			if got := c.Scheme(); got != tt.want {
				t.Errorf("Scheme() = %q, want %q", got, tt.want)
			}
		})
	}
}
EOF
